grep -v "^row_id" /Users/wolffbe/workspace/banter/testbed/results/19_db-full-cli-sdk-skills-sonnet/claude-sonnet-4-6/databricks/sdk/0.117.0/no-skills/feature/validate/1/task/data/events.csv | awk -F',' '
{
  row_id=$1; amount=$4; category=$5;
  # Check null/empty amount
  if (amount == "" || amount == "null") { print row_id " FAIL: null/empty amount"; next }
  # Check amount in [0, 10000]
  if (amount+0 < 0 || amount+0 > 10000) { print row_id " FAIL: amount out of range: " amount; next }
  # Check category
  if (category != "grocery" && category != "travel" && category != "salary" && category != "rent" && category != "other") { print row_id " FAIL: invalid category: " category; next }
}' | head -60

grep -v "^row_id" /Users/wolffbe/workspace/banter/testbed/results/19_db-full-cli-sdk-skills-sonnet/claude-sonnet-4-6/databricks/sdk/0.117.0/no-skills/feature/validate/1/task/data/events.csv | awk -F',' '{
  row_id=$1; amount=$4; category=$5;
  if (amount == "" || amount == "null") { print row_id " FAIL: null amount"; next }
  if (amount+0 < 0 || amount+0 > 10000) { print row_id " FAIL: amount=" amount; next }
  if (category !~ /^(grocery|travel|salary|rent|other)$/) { print row_id " FAIL: cat=" category; next }
}'

grep -v "^row_id" /Users/wolffbe/workspace/banter/testbed/results/19_db-full-cli-sdk-skills-sonnet/claude-sonnet-4-6/databricks/sdk/0.117.0/no-skills/feature/validate/1/task/data/events.csv | awk -F',' 'BEGIN{OFS=","} {
  row_id=$1; amount=$4; category=$5;
  valid=1;
  if (amount == "" || amount == "null") { valid=0; reason="null amount" }
  else if (amount+0 < 0 || amount+0 > 10000) { valid=0; reason="amount=" amount }
  else if (category != "grocery" && category != "travel" && category != "salary" && category != "rent" && category != "other") { valid=0; reason="cat=" category }
  if (!valid) print row_id, reason
}'
